const MBL_CODE_TO_CLUB = { NMD: "ns_matrix", KLT: "kl_titans", JST: "johor_tigers", PSY: "penang_sunrise", AS: "kl_aseel", SCW: "sarawak_cola", SGH: "selangor_hornbills" };

/* Team kits — pro colours as set by the designer, semi-pro taken from each club's logo. */
const KITS = {
  ns_matrix: { jersey: "#1d8a45", trim: "#ffd34d", panel: "#111316", shorts: "#1d8a45" },
  kl_titans: { jersey: "#17191e", trim: "#e2392f", panel: "#2f6fd8", shorts: "#17191e" },
  johor_tigers: { jersey: "#2a52c9", trim: "#ffffff", panel: "#e2392f", shorts: "#2a52c9" },
  penang_sunrise: { jersey: "#d8282b", trim: "#ffffff", panel: "#ffffff", shorts: "#d8282b" },
  kl_aseel: { jersey: "#f3f4f6", trim: "#17191e", panel: "#d8282b", shorts: "#9aa4b2" },
  sarawak_cola: { jersey: "#d8282b", trim: "#ff8a1f", panel: "#17191e", shorts: "#d8282b" },
  selangor_hornbills: { jersey: "#d8282b", trim: "#17191e", panel: "#17191e", shorts: "#d8282b" },
};
[["sp_mbc_kirin", "#0b8db1"], ["sp_gostrong", "#1a1c20"], ["sp_sba", "#cf2429"], ["sp_96bc", "#f07027"], ["sp_shinsei16", "#ee5626"], ["sp_speedhunters", "#f17128"], ["sp_borneo", "#538daf"], ["sp_farmcochem", "#eb2229"], ["sp_parkcity", "#e3101c"], ["sp_keeming", "#0c2f51"], ["sp_rising", "#0b8db1"]]
  .forEach(([id, c]) => { KITS[id] = { jersey: c, trim: "#ffffff", panel: sh(c, 0.6), shorts: c }; });
const STATE_KIT_COL = {
  "Selangor": ["#e8b400", "#d8282b"], "Johor": ["#2f56d1", "#e2392f"], "Kedah": ["#d63a2f", "#ffd34d"], "Kuala Lumpur": ["#2f56d1", "#ffd34d"],
  "Pulau Pinang": ["#3a8bd5", "#ffd34d"], "Perak": ["#e8c200", "#17191e"], "Sabah": ["#2e86de", "#e2392f"], "Sarawak": ["#f0a020", "#17191e"],
  "Negeri Sembilan": ["#e8c200", "#d8282b"], "Melaka": ["#d63a2f", "#2f56d1"], "Pahang": ["#f3f4f6", "#17191e"], "Kelantan": ["#d63a2f", "#ffffff"],
  "Terengganu": ["#f3f4f6", "#17191e"], "Perlis": ["#e8c200", "#2f56d1"], "Labuan": ["#2f56d1", "#ffffff"], "Putrajaya": ["#3a6bd5", "#ffd34d"],
};
function stateKit(hometown) {
  const k = HOMETOWNS.find(h => hometown && hometown.indexOf(h) === 0) || hometown;
  const [j, t] = STATE_KIT_COL[k] || ["#ff7a1a", "#ffffff"];
  return { jersey: j, trim: lum(j) > 200 ? "#17191e" : "#ffffff", panel: t, shorts: j };
}
function kitForPlayer(p) {
  if (!p) return null;
  if (p.clubId && KITS[p.clubId]) return KITS[p.clubId];
  if (p.abroad) return { jersey: "#f3f4f6", trim: "#1b1e25", panel: "#3060e0", shorts: "#f3f4f6" };
  if (p.uba) return { jersey: "#1b3f8f", trim: "#ffffff", panel: "#ffd34d", shorts: "#1b3f8f" };
  if (p.hblSeasonPending || (p.hblEver && p.age <= 18 && !p.clubId)) return { jersey: "#0f5c4a", trim: "#ffffff", panel: "#ffd34d", shorts: "#0f5c4a" };
  return stateKit(p.hometown);
}

