/* =====================================================================
   MATCHDAY GLUE — names, the "play the tournament first" hook used by
   the youth / national resolvers, and outcome mapping back to the
   shapes the rest of the game already uses.
===================================================================== */
const MD_LEAGUES_ON = true;
const MD_TOURNEYS_ON = true;
const MD_NAMES = { local: NPC_FILLER_NAMES, imports: MD_NAME_POOLS.imports, foreign: MD_NAME_POOLS.foreign, countries: MD_NAME_POOLS.countries };

/* While a resolver runs under mdRun, a tournament that hasn't been played yet
   stops it (throws) so the tournament can be played first; once played, the
   resolver is run again from the same starting point and picks the results up. */
let MD_CTX = null;
function mdNeed(tag, spec) {
  if (!MD_CTX) return null;
  const n = (MD_CTX.count[tag] = (MD_CTX.count[tag] || 0) + 1);
  const key = tag + "#" + n;
  if (MD_CTX.overrides[key]) return MD_CTX.overrides[key];
  const e = new Error("matchday:" + key);
  e.mdNeed = true; e.tag = key; e.spec = { kind: tag, ...(spec || {}) };
  throw e;
}

/* Youth tr formula, same weights the game's tournament generators use. */
function mdYouthTr(l) {
  return mdClamp(Math.round((l.ppg / 24) * 32 + (l.rpg / 13) * 16 + (l.apg / 6) * 14 + (l.spg / 3.1) * 12 + (l.bpg / 3) * 8 + (l.fgPct / 55) * 12 + (l.threePct / 44) * 6), 0, 100);
}
function mdStatsOut(comp) {
  const l = mdLine(comp.stats[MD_ME]) || { g: 0, ppg: 0, rpg: 0, apg: 0, spg: 0, bpg: 0, fgPct: 0, threePct: 0, mpg: 0 };
  return { ppg: l.ppg, rpg: l.rpg, apg: l.apg, spg: l.spg, bpg: l.bpg, fgPct: l.fgPct, threePct: l.threePct, tr: mdYouthTr(l), games: l.g, mpg: l.mpg };
}
const MD_AWARD_IDS = { ppg: "top_scorer", rpg: "top_rebounder", apg: "top_assists", spg: "top_steals", bpg: "top_blocks" };
function mdAwardIds(comp, statOnly) {
  const aw = mdAwards(comp);
  const out = [];
  Object.entries(aw.leaders).forEach(([k, id]) => { if (id === MD_ME) out.push(MD_AWARD_IDS[k]); });
  if (!statOnly) {
    if (aw.pot === MD_ME) out.push("pot");
    if (aw.finalMvp === MD_ME) out.push("final_mvp");
  }
  return { ids: out, tot: aw.tot.includes(MD_ME), raw: aw };
}

/* What a finished tournament hands back to the resolver that was waiting on it. */
function mdOutcome(comp) {
  const st = mdStatsOut(comp);
  const pl = mdMyPlacing(comp);
  const aw = mdAwardIds(comp, comp.kind === "u17" && comp.jump);
  if (comp.format === "fiba") {
    return { stats: st, qualified: comp.eliminated !== "qual", resultId: pl.id, tot: aw.tot, awards: aw.ids, place: pl.place };
  }
  if (comp.kind === "sea") {
    let idx = pl.id === "champion" ? 0 : pl.id === "runner_up" ? 1 : pl.id === "third" ? 2 : pl.id === "fourth" ? 3 : (pl.place >= 7 ? 5 : 4);
    return { stats: st, placeIdx: idx, standout: aw.tot || aw.ids.length > 0, awards: aw.ids };
  }
  return { stats: { ...st, outstanding: aw.tot }, teamResultId: pl.id, awards: aw.ids, tot: aw.tot };
}

/* Your role inside a youth team: starter if you're among its five best. */
function mdYouthRole(comp, p) {
  const mine = comp.entries[comp.myTeam] || [];
  const myOvr = mdOvr(MD_STATS.map(k => p.stats[k] || 40), p.position);
  const better = mine.filter(e => (e.o || e.ovr || 0) > myOvr).length;
  return better < 5 ? "Starter" : better < 8 ? "Rotation" : "Bench";
}

/* =====================================================================
   MATCHDAY SCREENS — competition hub, pre-game, live game, box score
   (layouts follow the approved prototype)
===================================================================== */
const MD_FLAGS = {"MAS": "data:image/svg+xml;base64,", "PHI": "data:image/svg+xml;base64,", "INA": "data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIGlkPSJmbGFnLWljb25zLWlkIiB2aWV3Qm94PSIwIDAgNjQwIDQ4MCI+CiAgPHBhdGggZmlsbD0iI2U3MDAxMSIgZD0iTTAgMGg2NDB2MjQwSDBaIi8+CiAgPHBhdGggZmlsbD0iI2ZmZiIgZD0iTTAgMjQwaDY0MHYyNDBIMFoiLz4KPC9zdmc+Cg==", "THA": "data:image/svg+xml;base64,", "SGP": "data:image/svg+xml;base64,", "LAO": "data:image/svg+xml;base64,", "AUS": "data:image/svg+xml;base64,", "NZL": "data:image/svg+xml;base64,", "JPN": "data:image/svg+xml;base64,", "CHN": "data:image/svg+xml;base64,", "TPE": "data:image/svg+xml;base64,", "VIE": "data:image/svg+xml;base64,"};
const MD_PHASE = { rs: "Regular season", grp: "Group stage", qual: "Qualifiers", xq: "Qualification for QF", qf: "Quarter-final", sf: "Semi-final", f: "Final", "3rd": "Third place" };

function mdTeam(comp, id) { return (comp && comp.teams && comp.teams[id]) || { id, name: id, short: id }; }
function mdTeamColor(t) {
  const k = (t && (t.kit || mdKitFor(t.id))) || null;
  const base = (t && t.color) || (k && k.jersey) || "#ff7a1a";
  if (lum(base) >= 45) return base;
  const alt = k && [k.panel, k.trim].find(c => c && lum(c) >= 45 && lum(c) <= 235);
  return alt || "#9aa4b2";
}
function MdBadge({ team, size = 32 }) {
  if (!team) return null;
  if (team.logo && LOGO[team.logo]) return <LogoPlate k={team.logo} size={size} title={team.name} />;
  const flag = team.flag && ((typeof FLAG_IMAGES !== "undefined" && FLAG_IMAGES[team.flag]) || MD_FLAGS[team.flag]);
  if (flag) return <LogoPlate src={flag} size={size} round={false} title={team.name} />;
  return (
    <span className="rd-logo bc" title={team.name} style={{ width: size, height: size, borderRadius: "50%", background: team.color || C.ink3, color: "#fff", fontSize: size * 0.34, fontWeight: 800 }}>
      {(team.short || team.name || "?").slice(0, 3).toUpperCase()}
    </span>
  );
}
function mdWL(comp, id, phases) {
  const ph = phases || ["rs", "grp", "qual"];
  let w = 0, l = 0;
  comp.games.forEach(g => {
    if (!g.res || !ph.includes(g.ph) || (g.h !== id && g.a !== id)) return;
    const mine = g.h === id ? 0 : 1;
    if (g.res.s[mine] > g.res.s[1 - mine]) w++; else l++;
  });
  return `${w}–${l}`;
}
function mdMyGames(comp) { return comp.games.filter(g => g.h === comp.myTeam || g.a === comp.myTeam); }
function mdNextMine(comp) { return comp.games.find(g => !g.res && (g.h === comp.myTeam || g.a === comp.myTeam)); }
function mdIsBig(comp, g) { return !!g && (g.ph !== "rs" && g.ph !== "grp" && g.ph !== "qual" || comp.rivalGame === g.i); }
function mdCanPlay(comp, g) { return !!g && !comp.seasonOut && !(comp.injuredUntil >= g.i); }
function mdPersonLook(comp, teamId, playerId, p) {
  if (playerId === MD_ME) return playerLook(p);
  const list = comp.entries[teamId] || [];
  const e = list.find(x => (x.k || x.id) === playerId);
  if (!e) return { ...DEFLOOK, anon: true };
  if (e.look) return e.look;
  return mdLookFor(e, comp.teams[teamId].kit || mdKitFor(teamId));
}

/* ---------- pixel court with the live shot chart ---------- */
function MdCourt({ shots, colors, ball }) {
  const ref = useRef(null);
  useEffect(() => {
    const cv = ref.current; if (!cv) return;
    const c = cv.getContext("2d"); c.imageSmoothingEnabled = false;
    const W = 188, H = 100;
    const R = (x, y, w, h, col) => { c.fillStyle = col; c.fillRect(Math.round(x), Math.round(y), Math.round(w), Math.round(h)); };
    R(0, 0, W, H, "#5a3a1e");
    for (let x = 0; x < W; x += 8) R(x, 0, 4, H, "#62401f");
    for (let y = 0; y < H; y += 6) R((y * 7) % 16, y, 1, 6, "#4e3218");
    const line = "rgba(255,255,255,.75)";
    R(2, 2, W - 4, 1, line); R(2, H - 3, W - 4, 1, line); R(2, 2, 1, H - 4, line); R(W - 3, 2, 1, H - 4, line); R(W / 2, 2, 1, H - 4, line);
    [0, 1].forEach(s => {
      const x0 = s ? W - 3 - 36 : 3;
      R(x0, 32, 36, 36, s ? (colors[1] + "55") : (colors[0] + "55"));
      R(x0, 32, 36, 1, line); R(x0, 67, 36, 1, line); R(s ? x0 : x0 + 35, 32, 1, 36, line);
      c.strokeStyle = line; c.lineWidth = 1; c.beginPath();
      const hx = s ? W - 12 : 12;
      c.arc(hx, 50, 42, s ? Math.PI * 0.5 : -Math.PI * 0.5, s ? Math.PI * 1.5 : Math.PI * 0.5, false); c.stroke();
      R(s ? W - 8 : 6, 46, 2, 9, "#f3f4f6"); R(hx - 2, 48, 4, 4, "#ff7a1a");
    });
    c.strokeStyle = line; c.beginPath(); c.arc(W / 2, 50, 11, 0, Math.PI * 2); c.stroke();
    (shots || []).slice(-28).forEach(s => {
      const col = colors[s.side] || "#fff";
      if (s.make) { R(s.x - 2, s.y - 2, 5, 5, "#0b0d12"); R(s.x - 1, s.y - 1, 3, 3, col); }
      else { R(s.x - 2, s.y - 2, 1, 1, col); R(s.x + 2, s.y - 2, 1, 1, col); R(s.x - 1, s.y - 1, 3, 3, col); R(s.x - 2, s.y + 2, 1, 1, col); R(s.x + 2, s.y + 2, 1, 1, col); }
    });
    if (ball) { R(ball.x - 2, ball.y - 2, 5, 5, "#0b0d12"); R(ball.x - 1, ball.y - 1, 3, 3, "#ff8a2e"); }
  }, [shots, colors, ball]);
  return <canvas ref={ref} width={188} height={100} className="px" style={{ width: "100%", height: "auto", borderRadius: 14, border: `1px solid ${C.line}` }} aria-label="Live shot chart" />;
}
function mdShotXY(e, idx) {
  const r = mdRng(mdHash("shot" + idx + ":" + e.pl));
  const s = e.side; // home attacks right
  const hx = s === 0 ? 176 : 12, dir = s === 0 ? -1 : 1;
  const ang = (r() - 0.5) * Math.PI * 0.92;
  const d = e.k === "ft" ? 26 : e.three ? 44 + r() * 5 : 4 + r() * 30;
  return { x: Math.round(hx + dir * Math.cos(ang) * d), y: Math.round(mdClamp(50 + Math.sin(ang) * d, 6, 94)), side: s, make: e.k === "ft" ? (e.m > 0 ? 1 : 0) : e.make };
}

/* ---------- competition hub ---------- */
function MdCompScreen({ player, comp, onPreGame, onSim, onSimBig, onSimAll, onFinish, onBox }) {
  const lay = useLayoutMode();
  const [tab, setTab] = useState(comp.type === "league" ? "table" : "groups");
  const next = mdNextMine(comp);
  const myGames = mdMyGames(comp);
  const played = myGames.filter(g => g.res);
  const meTeam = mdTeam(comp, comp.myTeam);
  const done = comp.done || (comp.format === "fiba" && mdFibaFinishedForMe(comp));
  const line = mdLine(comp.stats[MD_ME]);
  const canPlay = mdCanPlay(comp, next);
  const opp = next && mdTeam(comp, next.h === comp.myTeam ? next.a : next.h);
  const lbl = comp.kind === "mbl" ? "c_mbl" : comp.kind === "u20" || comp.kind === "u23" ? "c_dleague" : comp.logo;
  const tabs = comp.type === "league" ? [["table", "Standings"], ["sched", "Schedule"], ["lead", "Leaders"]].concat(comp.po ? [["bracket", "Playoffs"]] : [])
    : [["groups", comp.format === "fiba" && comp.stage === "qual" ? "Qualifiers" : "Groups"], ["bracket", "Knockouts"], ["sched", "Schedule"], ["lead", "Leaders"]];
  const resultChip = (g) => {
    const mine = g.h === comp.myTeam ? 0 : 1;
    const won = g.res && g.res.s[mine] > g.res.s[1 - mine];
    return <span className="bc" style={{ width: 22, color: won ? "#34d399" : "#f87171", fontWeight: 800 }}>{won ? "W" : "L"}</span>;
  };
  const tableRows = (ids, phases) => mdTable(comp, ids, phases);
  const Table = ({ rows, cut }) => (
    <table className="rd-table">
      <thead><tr><th>Team</th><th>GP</th><th>W</th><th>L</th><th className="rd-hide-phone">PF</th><th className="rd-hide-phone">PA</th><th>Diff</th></tr></thead>
      <tbody>{rows.map((r, i) => (
        <tr key={r.id} className={r.id === comp.myTeam ? "mine" : ""} style={cut && i === cut ? { borderTop: `2px solid ${C.amber}` } : undefined}>
          <td><span className="tn" style={{ display: "inline-flex", alignItems: "center", gap: 8 }}><span style={{ color: C.chalkDim, width: 16 }}>{i + 1}</span><MdBadge team={mdTeam(comp, r.id)} size={22} />{r.name}</span></td>
          <td>{r.gp}</td><td style={{ fontWeight: 700 }}>{r.w}</td><td>{r.l}</td><td className="rd-hide-phone">{r.pf}</td><td className="rd-hide-phone">{r.pa}</td>
          <td style={{ color: r.pf - r.pa > 0 ? "#34d399" : r.pf - r.pa < 0 ? "#f87171" : C.chalkDim }}>{r.pf - r.pa > 0 ? "+" : ""}{r.pf - r.pa}</td>
        </tr>))}</tbody>
    </table>
  );
  const ko = comp.type === "league" ? comp.po : comp.ko;
  return (
    <div style={{ padding: lay === "phone" ? "16px 12px 28px" : "26px 28px 40px", maxWidth: 1180, margin: "0 auto" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 16, flexWrap: "wrap" }}>
        {lbl && LOGO[lbl] ? <LogoPlate k={lbl} size={50} /> : <MdBadge team={meTeam} size={50} />}
        <div style={{ flex: 1, minWidth: 0 }}>
          <div className="rd-k">{comp.year} · {meTeam.name}</div>
          <div className="bc" style={{ fontSize: lay === "phone" ? 26 : 34, fontWeight: 800, color: C.chalk, lineHeight: 1 }}>{comp.label}</div>
        </div>
        <div style={{ display: "flex", gap: 18 }}>
          <div><div className="bc" style={{ fontSize: 30, fontWeight: 800, color: C.chalk, lineHeight: 1 }}>{mdWL(comp, comp.myTeam, ["rs", "grp", "qual", "xq", "qf", "sf", "f", "3rd"])}</div><div className="rd-k" style={{ fontSize: 9 }}>Record</div></div>
          {line && <div><div className="bc" style={{ fontSize: 30, fontWeight: 800, color: C.amberBright, lineHeight: 1 }}>{line.ppg.toFixed(1)}</div><div className="rd-k" style={{ fontSize: 9 }}>Your PPG</div></div>}
        </div>
      </div>
      {comp.intro && !played.length && (
        <div className="rd-card rd-up" style={{ padding: 14, marginBottom: 14, borderColor: C.amber, display: "flex", alignItems: "center", gap: 12 }}>
          <span style={{ fontSize: 22 }}>🏀</span>
          <span style={{ font: "500 13px Inter,sans-serif", color: C.chalk }}>{comp.intro}</span>
        </div>
      )}
      {comp.type === "league" && comp.leg && comp.leg.n > 1 && <PrYearRoad player={player} />}
      {comp.reunion && !played.length && (
        <div className="rd-card rd-up" style={{ padding: 14, marginBottom: 14, borderColor: "#34c37a", display: "flex", alignItems: "center", gap: 12 }}>
          <span style={{ display: "flex", flex: "none" }}>{comp.reunion.keys.slice(0, 3).map((k, i) => <span key={k} style={{ width: 40, height: 42, marginLeft: i ? -12 : 0, borderRadius: 10, background: "#14171c", border: "1px solid #34c37a", display: "flex", alignItems: "flex-end", justifyContent: "center", overflow: "hidden" }}><Sprite look={connLook(k)} style={{ width: 38, height: 40 }} /></span>)}</span>
          <span style={{ font: "500 13px Inter,sans-serif", color: C.chalk }}><b style={{ color: "#34c37a" }}>Reunion · </b>{comp.reunion.text}</span>
        </div>
      )}
      <div style={{ display: "grid", gridTemplateColumns: lay === "phone" ? "1fr" : "minmax(320px,420px) minmax(0,1fr)", gap: 16, alignItems: "start" }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
          {!done && next && (
            <div className="rd-card rd-up" style={{ padding: 16, borderColor: mdIsBig(comp, next) ? C.amber : C.line }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
                <span className="rd-k">Next game · {MD_PHASE[next.ph] || ""}{next.gnum ? ` · Game ${next.gnum}` : ""}</span>
                {mdIsBig(comp, next) && <span className="rd-chip" style={{ color: C.amberBright, borderColor: C.amber }}>{comp.rivalGame === next.i ? "Rivalry night" : "Big game"}</span>}
              </div>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10 }}>
                {[next.h, next.a].map((id, k) => (
                  <div key={id} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 6, textAlign: "center" }}>
                    <MdBadge team={mdTeam(comp, id)} size={56} />
                    <div style={{ font: "700 13px Inter,sans-serif", color: id === comp.myTeam ? C.amberBright : C.chalk }}>{mdTeam(comp, id).name}</div>
                    <div style={{ font: "500 11px Inter,sans-serif", color: C.chalkDim }}>{k === 0 ? "Home" : "Away"} · {mdWL(comp, id)}</div>
                  </div>
                ))}
              </div>
              <div style={{ textAlign: "center", font: "500 11.5px Inter,sans-serif", color: C.chalkDim, margin: "10px 0 12px" }}>{mdFmtDate(next.d)}{mdTeam(comp, next.h).venue ? ` · ${mdTeam(comp, next.h).venue}` : ""}</div>
              {!canPlay && <div className="rd-chip" style={{ width: "100%", justifyContent: "center", marginBottom: 10, color: "#fca5a5" }}>{comp.seasonOut ? "Out for the season — your team plays on" : "You're injured — sitting this one out"}</div>}
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                {canPlay && <button className="rd-btn" style={{ flex: 1 }} onClick={() => onPreGame(next.i)}>Play game <ChevronRight size={15} /></button>}
                <button className="rd-ghost" style={{ flex: canPlay ? undefined : 1 }} onClick={() => onSim(next.i)}>Sim game</button>
                <button className="rd-ghost" onClick={onSimBig} title="Sim until the next playoff, knockout or rivalry game">Sim to next big game</button>
              </div>
            </div>
          )}
          {!done && !next && (
            <div className="rd-card rd-up" style={{ padding: 16 }}>
              <div className="rd-k">{comp.type === "league" ? "Your season is over" : "You're out"}</div>
              <p style={{ font: "400 12.5px Inter,sans-serif", color: C.chalkDim, margin: "6px 0 12px" }}>The rest of the {comp.type === "league" ? "playoffs" : "tournament"} still has to be played.</p>
              <button className="rd-btn" style={{ width: "100%" }} onClick={onSimBig}>Sim to the end</button>
            </div>
          )}
          {done && (
            <div className="rd-card rd-up" style={{ padding: 16, borderColor: C.amber }}>
              <div className="rd-k">{comp.type === "league" ? "Season complete" : "Tournament complete"}</div>
              <div className="bc" style={{ fontSize: 26, fontWeight: 800, color: C.chalk, margin: "6px 0 4px" }}>{comp.champion ? `${mdTeam(comp, comp.champion).name} are champions` : "Your campaign is over"}</div>
              <p style={{ font: "400 12.5px Inter,sans-serif", color: C.chalkDim, margin: "0 0 12px" }}>See how your season adds up.</p>
              <button className="rd-btn" style={{ width: "100%" }} onClick={onFinish}>Continue <ChevronRight size={15} /></button>
            </div>
          )}
          {line && (
            <div className="rd-card" style={{ padding: 14 }}>
              <div className="rd-k" style={{ marginBottom: 8 }}>Your numbers · {line.g} games · {line.mpg} min</div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(5,1fr)", gap: 6, textAlign: "center" }}>
                {[["PTS", line.ppg], ["REB", line.rpg], ["AST", line.apg], ["STL", line.spg], ["BLK", line.bpg]].map(([k, v]) => (
                  <div key={k}><div className="bc" style={{ fontSize: 22, fontWeight: 800, color: C.chalk }}>{v.toFixed(1)}</div><div className="rd-k" style={{ fontSize: 9 }}>{k}</div></div>
                ))}
              </div>
              <div style={{ font: "500 11px Inter,sans-serif", color: C.chalkDim, marginTop: 8 }}>FG {line.fgPct}% · 3PT {line.threePct}% · FT {line.ftPct}%</div>
            </div>
          )}
          <div className="rd-card" style={{ padding: 12 }}>
            <div className="rd-k" style={{ marginBottom: 6 }}>Your results</div>
            {!played.length && <p style={{ font: "400 12px Inter,sans-serif", color: C.chalkDim, margin: 0 }}>No games played yet.</p>}
            {played.slice(-8).reverse().map(g => {
              const mine = g.h === comp.myTeam ? 0 : 1;
              const o = mdTeam(comp, mine ? g.h : g.a);
              const my = g.res.my;
              return (
                <button key={g.i} onClick={() => onBox && onBox(g.i)} style={{ display: "flex", alignItems: "center", gap: 8, width: "100%", padding: "7px 2px", borderBottom: "1px solid #1d1d1d", textAlign: "left" }}>
                  {resultChip(g)}<MdBadge team={o} size={20} />
                  <span style={{ flex: 1, minWidth: 0, font: "500 12.5px Inter,sans-serif", color: C.chalk, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{mine ? "@ " : "vs "}{o.name}</span>
                  <span className="bc" style={{ fontSize: 16, fontWeight: 800, color: C.chalk }}>{g.res.s[mine]}–{g.res.s[1 - mine]}</span>
                  <span style={{ width: 92, textAlign: "right", font: "500 11px Inter,sans-serif", color: C.chalkDim }}>{my && !my.dnp ? `${my.pts} pts · ${my.reb} reb` : "DNP"}</span>
                </button>
              );
            })}
          </div>
        </div>
        <div className="rd-card" style={{ padding: 12, minWidth: 0 }}>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 10 }}>
            {tabs.map(([id, l]) => <button key={id} className={"rd-tab " + (tab === id ? "on" : "")} onClick={() => setTab(id)}>{l}</button>)}
          </div>
          <div style={{ overflowX: "auto" }}>
            {tab === "table" && <Table rows={tableRows(Object.keys(comp.teams), ["rs"])} cut={comp.kind === "mbl" ? 4 : 8} />}
            {tab === "groups" && (comp.format === "fiba" && (comp.stage === "qual" || !comp.groups) ? <><div className="rd-k" style={{ margin: "4px 0 6px" }}>{comp.qualLabel} · top 3 go to the Asia Cup</div><Table rows={tableRows(Object.keys(comp.teams).filter(x => ["MAS", "PHI", "INA", "THA", "SGP"].includes(x)), ["qual"])} cut={3} /></>
              : (comp.groups || []).map(g => (
                <div key={g.id} style={{ marginBottom: 12 }}>
                  <div className="rd-k" style={{ margin: "4px 0 6px" }}>Group {g.id}</div>
                  <Table rows={tableRows(g.teams, ["grp"])} cut={comp.format === "fiba" ? 1 : 2} />
                </div>)))}
            {tab === "bracket" && (!ko || !ko.length ? <p style={{ font: "400 12.5px Inter,sans-serif", color: C.chalkDim }}>{comp.type === "league" ? "The top " + (comp.kind === "mbl" ? 4 : 8) + " make the playoffs once the regular season ends." : "The knockouts start after the group stage."}</p>
              : <div style={{ display: "grid", gridTemplateColumns: lay === "phone" ? "1fr" : "repeat(auto-fit,minmax(220px,1fr))", gap: 10 }}>
                {ko.map((s, i) => (
                  <div key={i} style={{ background: C.ink3, border: `1px solid ${s.a === comp.myTeam || s.b === comp.myTeam ? C.amber : C.line}`, borderRadius: 12, padding: 10 }}>
                    <div className="rd-k" style={{ fontSize: 9, marginBottom: 6 }}>{s.round}{s.bo > 1 ? ` · best of ${s.bo}` : ""}</div>
                    {[[s.a, s.wa], [s.b, s.wb]].map(([id, w]) => (
                      <div key={id} style={{ display: "flex", alignItems: "center", gap: 8, padding: "3px 0", opacity: s.winner && s.winner !== id ? 0.5 : 1 }}>
                        <MdBadge team={mdTeam(comp, id)} size={20} /><span style={{ flex: 1, font: `${s.winner === id ? 700 : 500} 12.5px Inter,sans-serif`, color: C.chalk }}>{mdTeam(comp, id).name}</span>
                        <span className="bc" style={{ fontSize: 17, fontWeight: 800, color: C.chalk }}>{s.bo > 1 ? w : (s.games[0] != null && comp.games[s.games[0]].res ? comp.games[s.games[0]].res.s[comp.games[s.games[0]].h === id ? 0 : 1] : "")}</span>
                      </div>
                    ))}
                  </div>
                ))}
              </div>)}
            {tab === "sched" && myGames.map(g => {
              const mine = g.h === comp.myTeam ? 0 : 1;
              const o = mdTeam(comp, mine ? g.h : g.a);
              return (
                <div key={g.i} style={{ display: "flex", alignItems: "center", gap: 8, padding: "7px 2px", borderBottom: "1px solid #1d1d1d", opacity: g.res ? 1 : 0.85 }}>
                  <span style={{ width: 132, font: "500 11px Inter,sans-serif", color: C.chalkDim }}>{mdFmtDate(g.d).split(" · ")[0]}</span>
                  <MdBadge team={o} size={20} />
                  <span style={{ flex: 1, minWidth: 0, font: "500 12.5px Inter,sans-serif", color: C.chalk, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{mine ? "@ " : "vs "}{o.name}</span>
                  {mdIsBig(comp, g) && !g.res && <span className="rd-chip" style={{ fontSize: 10, color: C.amberBright }}>{MD_PHASE[g.ph] && g.ph !== "rs" ? MD_PHASE[g.ph] : "Rivalry"}</span>}
                  {g.res ? <><span className="bc" style={{ fontSize: 15, fontWeight: 800, color: g.res.s[mine] > g.res.s[1 - mine] ? "#34d399" : "#f87171" }}>{g.res.s[mine]}–{g.res.s[1 - mine]}</span></> : <span style={{ font: "500 11px Inter,sans-serif", color: C.chalkDim }}>{MD_PHASE[g.ph]}</span>}
                </div>
              );
            })}
            {tab === "lead" && (
              <div style={{ display: "grid", gridTemplateColumns: lay === "phone" ? "1fr" : "1fr 1fr", gap: 14 }}>
                {[["ppg", "Points"], ["rpg", "Rebounds"], ["apg", "Assists"], ["spg", "Steals"]].map(([k, l]) => (
                  <div key={k}>
                    <div className="rd-k" style={{ marginBottom: 4 }}>{l}</div>
                    {mdLeaders(comp, k, 5).map((x, i) => (
                      <div key={x.id} style={{ display: "flex", alignItems: "center", gap: 8, padding: "4px 0", borderBottom: "1px solid #1d1d1d" }}>
                        <span style={{ width: 14, color: C.chalkDim, font: "600 11px Inter,sans-serif" }}>{i + 1}</span>
                        <span style={{ width: 26, height: 28, borderRadius: 6, overflow: "hidden", background: "#1d2230", flexShrink: 0 }}><Sprite look={mdPersonLook(comp, x.team, x.id, player)} still style={{ width: 26, height: 28 }} /></span>
                        <span style={{ flex: 1, minWidth: 0, font: `${x.me ? 700 : 500} 12px Inter,sans-serif`, color: x.me ? C.amberBright : C.chalk, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{x.me ? player.name : x.name}</span>
                        <MdBadge team={mdTeam(comp, x.team)} size={16} />
                        <span className="bc" style={{ width: 38, textAlign: "right", fontSize: 16, fontWeight: 800, color: C.chalk }}>{x.value.toFixed(1)}</span>
                      </div>
                    ))}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

/* ---------- pre-game ---------- */
function MdPregameScreen({ player, comp, gi, onTip, onSimFinal, onBack }) {
  const lay = useLayoutMode();
  const [plan, setPlan] = useState("balanced");
  const g = comp.games[gi];
  const H = mdTeam(comp, g.h), A = mdTeam(comp, g.a);
  const oppId = g.h === comp.myTeam ? g.a : g.h;
  const row = id => {
    const r = { gp: 0, w: 0, l: 0, pf: 0, pa: 0 };
    comp.games.forEach(x => {
      if (!x.res || (x.h !== id && x.a !== id)) return;
      const m = x.h === id ? 0 : 1;
      r.gp++; r.pf += x.res.s[m]; r.pa += x.res.s[1 - m];
      if (x.res.s[m] > x.res.s[1 - m]) r.w++; else r.l++;
    });
    return r;
  };
  const rh = row(g.h), ra = row(g.a);
  const per = (r, k) => r.gp ? r[k] / r.gp : 0;
  const tape = [["Points", per(rh, "pf"), per(ra, "pf")], ["Allowed", per(rh, "pa"), per(ra, "pa")], ["Win %", rh.gp ? rh.w / rh.gp * 100 : 0, ra.gp ? ra.w / ra.gp * 100 : 0]];
  const oppPlayers = (comp.entries[oppId] || []).map(e => ({ id: e.k || e.id, name: e.n || e.name, ovr: e.o || e.ovr, pos: e.pos }));
  const oppStar = oppPlayers.map(x => ({ ...x, l: mdLine(comp.stats[x.id]) })).sort((a, b) => ((b.l && b.l.ppg) || b.ovr / 10) - ((a.l && a.l.ppg) || a.ovr / 10))[0];
  const myLine = mdLine(comp.stats[MD_ME]);
  const mine = (comp.entries[comp.myTeam] || []).map(e => ({ id: e.k || e.id, name: e.n || e.name, ovr: e.o || e.ovr, pos: e.pos, imp: e.imp })).sort((a, b) => b.ovr - a.ovr);
  const role = comp.myRole || player.starterStatus || "Rotation";
  const five = (role === "Starter" ? [{ id: MD_ME, name: player.name, pos: player.position, me: true }] : []).concat(mine).slice(0, 5);
  const cols = [mdTeamColor(H), mdTeamColor(A)];
  return (
    <div style={{ padding: lay === "phone" ? "14px 12px 28px" : "24px 28px 40px", maxWidth: 1180, margin: "0 auto" }}>
      <div className="rd-card rd-up" style={{ overflow: "hidden", position: "relative", padding: lay === "phone" ? "18px 12px" : "26px 22px", background: `linear-gradient(90deg, ${cols[0]}44, ${C.ink2} 42%, ${C.ink2} 58%, ${cols[1]}44)` }}>
        <div style={{ display: "grid", gridTemplateColumns: "1fr auto 1fr", alignItems: "center", gap: 10 }}>
          {[H, A].map((t, k) => (
            <div key={t.id} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 8, textAlign: "center", order: k ? 3 : 1 }}>
              <MdBadge team={t} size={lay === "phone" ? 64 : 104} />
              <div className="bc" style={{ fontSize: lay === "phone" ? 18 : 26, fontWeight: 800, color: t.id === comp.myTeam ? C.amberBright : C.chalk, lineHeight: 1 }}>{t.name}</div>
              <div style={{ font: "500 11.5px Inter,sans-serif", color: C.chalkDim }}>{mdWL(comp, t.id)}{k === 0 ? " · Home" : " · Away"}</div>
            </div>
          ))}
          <div style={{ order: 2, textAlign: "center", padding: "0 6px" }}>
            <div className="bc" style={{ fontSize: lay === "phone" ? 30 : 46, fontWeight: 800, color: C.chalk }}>VS</div>
            <div style={{ font: "500 11px Inter,sans-serif", color: C.chalkDim, maxWidth: 170 }}>{mdFmtDate(g.d)}</div>
            {H.venue && <div style={{ font: "500 11px Inter,sans-serif", color: C.chalkDim, marginTop: 3, maxWidth: 170 }}>{H.venue}</div>}
            <div className="rd-chip" style={{ marginTop: 8 }}>{MD_PHASE[g.ph]}{g.gnum ? ` · G${g.gnum}` : ""}</div>
          </div>
        </div>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: lay === "phone" ? "1fr" : "minmax(0,5fr) minmax(0,7fr)", gap: 14, marginTop: 14 }}>
        <div className="rd-card" style={{ padding: 14 }}>
          <div className="rd-k" style={{ marginBottom: 10 }}>Tale of the tape · per game</div>
          {tape.map(([k, a, b]) => {
            const t = a + b || 1;
            return (
              <div key={k} style={{ display: "grid", gridTemplateColumns: "44px 1fr 64px 1fr 44px", alignItems: "center", gap: 8, marginBottom: 10 }}>
                <b className="bc" style={{ fontSize: 18, color: C.chalk }}>{a.toFixed(k === "Win %" ? 0 : 1)}</b>
                <div style={{ height: 6, background: C.ink3, borderRadius: 4, display: "flex", justifyContent: "flex-end" }}><i style={{ width: `${a / t * 100}%`, background: cols[0], borderRadius: 4 }} /></div>
                <span style={{ textAlign: "center", font: "600 10.5px Inter,sans-serif", color: C.chalkDim }}>{k}</span>
                <div style={{ height: 6, background: C.ink3, borderRadius: 4 }}><i style={{ display: "block", height: "100%", width: `${b / t * 100}%`, background: cols[1], borderRadius: 4 }} /></div>
                <b className="bc" style={{ fontSize: 18, color: C.chalk, textAlign: "right" }}>{b.toFixed(k === "Win %" ? 0 : 1)}</b>
              </div>
            );
          })}
          <div className="rd-k" style={{ margin: "14px 0 8px" }}>Game plan</div>
          <div style={{ display: "flex", gap: 6 }}>
            {[["push", "Push the pace"], ["balanced", "Balanced"], ["grind", "Grind it out"]].map(([id, l]) => <button key={id} className={"rd-tab " + (plan === id ? "on" : "")} style={{ flex: 1 }} onClick={() => setPlan(id)}>{l}</button>)}
          </div>
          <p style={{ font: "400 11.5px Inter,sans-serif", color: C.chalkDim, margin: "8px 0 0" }}>{plan === "push" ? "More possessions and a few more turnovers — good when you have the better athletes." : plan === "grind" ? "Fewer possessions, safer with the ball — keeps a stronger side within reach." : "Play your normal game."}</p>
        </div>
        <div className="rd-card" style={{ padding: 14 }}>
          <div className="rd-k" style={{ marginBottom: 10 }}>Key matchup</div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr auto 1fr", alignItems: "center", gap: 10 }}>
            {[[MD_ME, player.name, myLine, comp.myTeam], oppStar ? [oppStar.id, oppStar.name, oppStar.l, oppId] : null].map((x, k) => x && (
              <div key={k} style={{ display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center", gap: 6, order: k ? 3 : 1 }}>
                <div style={{ width: 96, height: 100, borderRadius: 14, background: "radial-gradient(70% 70% at 50% 60%, #26314a, #0b0d12)", display: "flex", alignItems: "flex-end", justifyContent: "center", overflow: "hidden" }}>
                  <Sprite look={mdPersonLook(comp, x[3], x[0], player)} style={{ width: 90, height: 95 }} />
                </div>
                <b style={{ font: "700 13px Inter,sans-serif", color: k ? C.chalk : C.amberBright }}>{x[1]}</b>
                <small style={{ font: "500 11px Inter,sans-serif", color: C.chalkDim }}>{x[2] ? `${x[2].ppg} PPG · ${x[2].rpg} RPG` : "First game"}</small>
              </div>
            ))}
            <span className="bc" style={{ order: 2, fontSize: 22, fontWeight: 800, color: C.chalkDim }}>VS</span>
          </div>
        </div>
      </div>
      <MdFamiliar player={player} comp={comp} gi={gi} />
      <div className="rd-card" style={{ padding: 14, marginTop: 14 }}>
        <div className="rd-k" style={{ marginBottom: 10, display: "flex", alignItems: "center", gap: 8 }}><MdBadge team={mdTeam(comp, comp.myTeam)} size={20} /> Starting five {role !== "Starter" ? "· you come off the bench" : ""}</div>
        <div style={{ display: "grid", gridTemplateColumns: lay === "phone" ? "repeat(3,1fr)" : "repeat(5,1fr)", gap: 10 }}>
          {five.map(x => (
            <div key={x.id} style={{ background: x.me ? "rgba(249,115,22,.10)" : C.ink3, border: `1px solid ${x.me ? C.amber : C.line}`, borderRadius: 12, padding: 8, textAlign: "center" }}>
              <div style={{ height: 84, display: "flex", alignItems: "flex-end", justifyContent: "center" }}><Sprite look={mdPersonLook(comp, comp.myTeam, x.id, player)} full ph={x.id.length} style={{ height: 82, width: "auto" }} /></div>
              <div style={{ font: "700 11.5px Inter,sans-serif", color: x.me ? C.amberBright : C.chalk, marginTop: 6, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{x.me ? player.name : x.name}</div>
              <div style={{ font: "500 10.5px Inter,sans-serif", color: C.chalkDim }}>{x.pos}{x.imp ? " · Import" : ""}</div>
            </div>
          ))}
        </div>
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", gap: 10, marginTop: 16, flexWrap: "wrap" }}>
        <button className="rd-ghost" onClick={onBack}>← Schedule</button>
        <div style={{ display: "flex", gap: 10 }}>
          <button className="rd-ghost" onClick={() => onSimFinal(plan)}>Sim to final</button>
          <button className="rd-btn" onClick={() => onTip(plan)}>Tip off ▶</button>
        </div>
      </div>
    </div>
  );
}

/* ---------- live game ---------- */
const MD_SPEEDS = [1, 2, 4];
function mdEvText(e, name) {
  if (e.k === "tov") return `${name} turns it over${e.st ? "" : ""}`;
  if (e.k === "ft") return `${name} makes ${e.m} of ${e.n} free throws`;
  if (e.k === "oreb") return `${name} grabs the offensive board`;
  if (e.k === "dreb") return `${name} rebounds`;
  if (e.make) return e.three ? `${name} drills a three` : ["scores at the rim", "hits the pull-up", "finishes through contact", "knocks down the jumper"][(name.length + e.t) % 4].replace(/^/, name + " ");
  return e.blk ? `${name}'s shot is blocked` : e.three ? `${name} misses from deep` : `${name} misses the jumper`;
}
/* Where the live feed was, so leaving through the menu and coming back resumes it. */
let MD_LIVE_POS = { g: null, n: 0 };
function MdLiveScreen({ player, comp, game, onClutch, onDone }) {
  const lay = useLayoutMode();
  const [shown, setShown] = useState(() => MD_LIVE_POS.g === game ? MD_LIVE_POS.n : 0);
  useEffect(() => { MD_LIVE_POS = { g: game, n: shown }; }, [game, shown]);
  const [speed, setSpeed] = useState(1);
  const [run, setRun] = useState(true);
  const [clutchBang, setClutchBang] = useState(null);
  const g = game;
  const names = useMemo(() => {
    const m = {};
    g.T.forEach(t => t.roster.forEach(p => { m[p.id] = p.me ? player.name : p.name; }));
    return m;
  }, [g]);
  const looks = useMemo(() => {
    const m = {};
    g.T.forEach((t, s) => t.roster.forEach(p => { m[p.id] = p.me ? playerLook(player) : (p.look || mdPersonLook(comp, t.id, p.id, player)); }));
    return m;
  }, [g]);
  const total = g.ev.length;
  const waitingClutch = !!g.clutch && shown >= total;
  const ended = g.final && shown >= total;
  useEffect(() => {
    if (!run || shown >= total) return undefined;
    const t = setTimeout(() => setShown(s => Math.min(total, s + 1)), Math.max(60, 520 / speed));
    return () => clearTimeout(t);
  }, [run, shown, total, speed]);
  const evs = g.ev.slice(0, shown);
  const last = evs[evs.length - 1];
  const score = last ? [last.h, last.a] : [0, 0];
  const clock = last ? `${Math.floor(last.t / 60)}:${String(last.t % 60).padStart(2, "0")}` : "10:00";
  const qtr = ended ? "FINAL" : last ? `Q${last.q + 1}` : "Q1";
  const shots = useMemo(() => evs.map((e, i) => (e.k === "shot" || e.k === "ft") ? mdShotXY(e, i) : null).filter(Boolean), [shown]);
  const my = useMemo(() => {
    const m = { pts: 0, fgm: 0, fga: 0, tpm: 0, tpa: 0, reb: 0, ast: 0 };
    evs.forEach(e => {
      if (e.pl === MD_ME) {
        if (e.k === "shot") { m.fga++; if (e.three) m.tpa++; if (e.make) { m.fgm++; m.pts += e.pts; if (e.three) m.tpm++; } }
        if (e.k === "ft") m.pts += e.m;
        if (e.k === "oreb" || e.k === "dreb") m.reb++;
      }
      if (e.ast === MD_ME) m.ast++;
      if (e.k === "shot" && e.and1 && e.pl === MD_ME) m.pts++;
    });
    return m;
  }, [shown]);
  const mom = useMemo(() => {
    let v = 50;
    evs.slice(-14).forEach(e => { if ((e.k === "shot" && e.make) || (e.k === "ft" && e.m)) v += (e.side === 0 ? 1 : -1) * (e.pts || e.m) * 3.5; });
    return mdClamp(v, 8, 92);
  }, [shown]);
  const T = g.teams;
  const cols = [mdTeamColor(T[0]), mdTeamColor(T[1])];
  const skip = () => { setRun(true); setShown(total); };
  const pick = (id) => { const res = onClutch(id); setClutchBang(res); setTimeout(() => setClutchBang(null), 1600); };
  return (
    <div style={{ padding: lay === "phone" ? "12px 10px 24px" : "20px 24px 32px", maxWidth: 1180, margin: "0 auto" }}>
      <div className="rd-card" style={{ display: "grid", gridTemplateColumns: "1fr auto 1fr", alignItems: "center", gap: 10, padding: lay === "phone" ? 10 : 14, background: `linear-gradient(90deg, ${cols[0]}33, ${C.ink2} 40%, ${C.ink2} 60%, ${cols[1]}33)` }}>
        {[0, 1].map(s => (
          <div key={s} style={{ display: "flex", alignItems: "center", gap: 10, justifyContent: s ? "flex-end" : "flex-start", order: s ? 3 : 1, flexDirection: s ? "row-reverse" : "row" }}>
            <MdBadge team={T[s]} size={lay === "phone" ? 34 : 48} />
            {lay !== "phone" && <div style={{ textAlign: s ? "right" : "left" }}><b style={{ font: "700 14px Inter,sans-serif", color: C.chalk }}>{T[s].name}</b><div style={{ font: "500 11px Inter,sans-serif", color: C.chalkDim }}>{s ? "Away" : "Home"}</div></div>}
            <span className="bc" style={{ fontSize: lay === "phone" ? 34 : 46, fontWeight: 800, color: C.chalk, minWidth: 54, textAlign: "center" }}>{score[s]}</span>
          </div>
        ))}
        <div style={{ order: 2, textAlign: "center" }}>
          <div className="bc" style={{ fontSize: 22, fontWeight: 800, color: C.amberBright }}>{ended ? "FINAL" : clock}</div>
          <div className="p8" style={{ fontSize: 8, color: C.chalkDim, marginTop: 4 }}>{ended ? (g.ot ? "OT" : "") : qtr}</div>
        </div>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: lay === "phone" ? "1fr" : lay === "land" ? "minmax(0,1.15fr) minmax(230px,1fr)" : "minmax(0,1.5fr) minmax(300px,1fr)", gap: 14, marginTop: 14 }}>
        <div>
          <MdCourt shots={shots} colors={cols} ball={shots[shots.length - 1]} />
          <div className="rd-card" style={{ display: "flex", alignItems: "center", gap: 12, padding: 10, marginTop: 10, flexWrap: "wrap" }}>
            {!ended ? (
              <>
                <button className="rd-btn" style={{ width: 44, padding: 0, height: 40 }} onClick={() => setRun(r => !r)} aria-label={run ? "Pause" : "Play"}>{run ? "❚❚" : "▶"}</button>
                <div style={{ display: "flex", gap: 4 }}>
                  {MD_SPEEDS.map(s => <button key={s} className={"rd-tab " + (speed === s ? "on" : "")} onClick={() => setSpeed(s)}>{s}×</button>)}
                  <button className="rd-tab" onClick={skip}>Skip</button>
                </div>
              </>
            ) : <button className="rd-btn" onClick={onDone}>Box score <ChevronRight size={15} /></button>}
            <div style={{ display: "flex", gap: 14, marginLeft: "auto" }}>
              {[["PTS", my.pts], ["FG", `${my.fgm}/${my.fga}`], ["3PT", `${my.tpm}/${my.tpa}`], ["REB", my.reb], ["AST", my.ast]].map(([k, v]) => (
                <div key={k} style={{ textAlign: "center" }}><div className="bc" style={{ fontSize: 20, fontWeight: 800, color: k === "PTS" ? C.amberBright : C.chalk }}>{v}</div><div className="rd-k" style={{ fontSize: 8.5 }}>{k}</div></div>
              ))}
            </div>
            <div style={{ flexBasis: "100%", display: "flex", alignItems: "center", gap: 8 }}>
              <span className="rd-k" style={{ fontSize: 9 }}>Momentum</span>
              <div style={{ flex: 1, height: 6, borderRadius: 4, background: cols[1] + "88", overflow: "hidden" }}><div style={{ width: `${mom}%`, height: "100%", background: cols[0], transition: "width .4s" }} /></div>
            </div>
          </div>
        </div>
        <div className="rd-card" style={{ padding: 10, maxHeight: lay === "phone" ? 300 : 460, overflowY: "auto" }} aria-live="polite">
          <div className="rd-k" style={{ marginBottom: 6 }}>Play-by-play</div>
          {evs.slice(-40).reverse().map((e, i) => (
            <div key={shown - i} style={{ display: "flex", alignItems: "center", gap: 8, padding: "5px 0", borderBottom: "1px solid #1d1d1d", background: e.pl === MD_ME ? "rgba(249,115,22,.07)" : undefined }}>
              <span style={{ width: 44, font: "500 10.5px Inter,sans-serif", color: C.chalkDim }}>Q{e.q + 1} {Math.floor(e.t / 60)}:{String(e.t % 60).padStart(2, "0")}</span>
              <span style={{ width: 22, height: 23, borderRadius: 5, overflow: "hidden", background: "#1d2230", flexShrink: 0 }}><Sprite look={looks[e.pl]} still style={{ width: 22, height: 23 }} /></span>
              <span style={{ flex: 1, minWidth: 0, font: "500 12px Inter,sans-serif", color: C.chalk }}>{mdEvText(e, names[e.pl] || "")}{e.ast && e.make ? <span style={{ color: C.chalkDim }}> · ast {(names[e.ast] || "").split(" ")[0]}</span> : null}{e.clutch ? " 🔥" : ""}</span>
              <span className="bc" style={{ fontSize: 14, fontWeight: 700, color: C.chalkDim }}>{e.h}–{e.a}</span>
            </div>
          ))}
          {!evs.length && <p style={{ font: "400 12px Inter,sans-serif", color: C.chalkDim }}>Tip-off…</p>}
        </div>
      </div>
      {waitingClutch && !clutchBang && (
        <div className="rd-modal" role="dialog" aria-modal="true" aria-label="Clutch moment">
          <div className="rd-card" style={{ width: "min(560px,100%)", padding: 18, background: "#101012" }}>
            <span className="rd-chip" style={{ color: C.amberBright, borderColor: C.amber }}>🔥 Clutch moment · Q4 {Math.floor(g.clutch.t / 60)}:{String(g.clutch.t % 60).padStart(2, "0")}</span>
            <div className="bc" style={{ fontSize: 30, fontWeight: 800, color: C.chalk, margin: "10px 0 4px" }}>Ball's in your hands</div>
            <p style={{ font: "400 13px Inter,sans-serif", color: C.chalkDim, margin: "0 0 12px" }}>{g.clutch.margin === 0 ? "Tied game." : g.clutch.margin > 0 ? `Up ${g.clutch.margin}.` : `Down ${-g.clutch.margin}.`} Shot clock at 6. What's the call?</p>
            {g.clutch.options.map(o => (
              <button key={o.id} className="choice-card" onClick={() => pick(o.id)} style={{ display: "flex", alignItems: "center", gap: 12, width: "100%", textAlign: "left", padding: 12, marginBottom: 8, borderRadius: 12, background: C.ink3, border: `1px solid ${C.line}` }}>
                <span style={{ fontSize: 22 }}>{o.id === "three" ? "🎯" : o.id === "drive" ? "⚡" : "🤝"}</span>
                <span style={{ flex: 1 }}><b style={{ display: "block", font: "700 14px Inter,sans-serif", color: C.chalk }}>{o.label}</b><small style={{ font: "400 11.5px Inter,sans-serif", color: C.chalkDim }}>{o.sub}</small></span>
                <span className="bc" style={{ fontSize: 20, fontWeight: 800, color: C.amberBright }}>{Math.round(o.chance * 100)}%</span>
              </button>
            ))}
          </div>
        </div>
      )}
      {clutchBang && (
        <div className="rd-modal" aria-live="assertive">
          <div className="rd-card" style={{ padding: 26, textAlign: "center", background: "#101012" }}>
            <div className="bc rd-up" style={{ fontSize: 54, fontWeight: 800, color: clutchBang.made ? C.amberBright : "#94a3b8" }}>{clutchBang.made ? "BANG" : "NO GOOD"}</div>
            <div style={{ font: "500 14px Inter,sans-serif", color: C.chalk }}>{clutchBang.made ? `${clutchBang.label} — it's good.` : `${clutchBang.label} — it rims out.`}</div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ---------- box score ---------- */
