      if (document.fonts && document.fonts.ready) await document.fonts.ready;
      let flagImg = null;
      const flagSrc = FLAG_IMAGES[p.hometown];
      if (flagSrc) flagImg = await new Promise(res => { const im = new Image(); im.onload = () => res(im); im.onerror = () => res(null); im.src = flagSrc; });
      const canvas = generateCareerCardCanvas(p, buildCareerSummary(p.history), title, flagImg);
      const blob = await new Promise((res, rej) => canvas.toBlob(b => b ? res(b) : rej(new Error("toBlob")), "image/png"));
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a"); a.href = url; a.download = `${(p.name || "career").replace(/\s+/g, "_")}_career_card.png`; document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 2000);
