  handHeart: "\u2764\uFE0F",      // give back / free clinic
  tieDollar: "\u{1F4BC}",       // paid corporate gig
  flair: "\u2728",             // play your natural, flashy game
  rulebook: "\u{1F4D6}",        // fall in line / the system
  trophyCash: "\u{1F3C6}",      // enter the tournament
