    const checkpoint = msPickMidseason(p, comp);
    if (checkpoint.type !== "special") p.msHist = [...(p.msHist || []).filter(h => p.year - h.y < 6), { id: checkpoint.type, y: p.year }];
    if (checkpoint.type === "recap") p.pendingSecondHalf = { ...p.pendingSecondHalf, recapShown: true };
    setPlayer(p);
    save(p);
