    const mineGames = comp.games.filter(g => g.res && g.res.my && !g.res.my.dnp && (g.h === comp.myTeam || g.a === comp.myTeam));
    const best = mineGames.slice().sort((a, b) => b.res.my.pts - a.res.my.pts)[0];
    if (best) stats.bestGame = { pts: best.res.my.pts, reb: best.res.my.reb, ast: best.res.my.ast };
    const inj = comp.injuries || [];
